/// <summary>
/// Bug 347656: [MS] - E2E - CB201 - EA to CA Conversion Error when Unit is set to "CA" Case - ALM Rebate #2603240030004457
/// </summary>
/// <param name = "_rebateTrans"></param>
/// <param name = "_rebateRefQty"></param>
/// <param name = "_fromUnit"></param>
/// <param name = "_toUnit"></param>
/// <param name = "_roundAbsoluteValue"></param>
/// <returns></returns>
protected TAMRebateQty convertRebateTransactionQuantityUsingConverter(
TAMRebateTrans _rebateTrans,
TAMRebateQty _rebateRefQty,
UnitOfMeasureSymbol _fromUnit,
UnitOfMeasureSymbol _toUnit,
NoYes _roundAbsoluteValue)
{
    TAMRebateQty qty;
    METSalesUnit defaultOrderUnit;

    if (rebateJournalTrans.metParmNeedUnitConversion() && (_fromUnit == METConstants::UnitIdEA && _toUnit == METConstants::unitCA))
    {
        [_rebateRefQty, defaultOrderUnit] = this.metPerformAdditionalConversion(_rebateTrans, _rebateRefQty, _fromUnit, _toUnit, _roundAbsoluteValue);

        _fromUnit = defaultOrderUnit;
    }

    qty = next convertRebateTransactionQuantityUsingConverter(_rebateTrans, _rebateRefQty, _fromUnit, _toUnit, _roundAbsoluteValue);
    return qty;
}

private container metPerformAdditionalConversion(
    TAMRebateTrans _rebateTrans,
    TAMRebateQty _rebateRefQty,
    UnitOfMeasureSymbol _fromUnit,
    UnitOfMeasureSymbol _toUnit,
    NoYes _roundAbsoluteValue)
{
    METSalesUnit defaultOrderUnit;

    if (!EcoResProductUnitConverter::canBeConvertedForReleasedProduct(_rebateTrans.ItemId,
        _rebateTrans.InventDimId,
        this.findUnitOfMeasureRecId(_fromUnit),
        this.findUnitOfMeasureRecId(_toUnit)))
    {
        defaultOrderUnit = rebateJournalTrans.metParmDefaultOrderUnit();

        if (defaultOrderUnit == '' || defaultOrderUnit == _toUnit)
        {
            throw Error(strFmt('@SYS50546', _fromUnit, _toUnit));
        }

        _rebateRefQty = EcoResProductUnitConverter::convertForReleasedProduct(
                            _rebateTrans.ItemId,
                            _rebateTrans.InventDimId,
                            _rebateRefQty,
                            this.findUnitOfMeasureRecId(_fromUnit),
                            this.findUnitOfMeasureRecId(defaultOrderUnit),
                            _roundAbsoluteValue,
                            NoYes::No);

        _fromUnit = defaultOrderUnit;
    }

    return [_rebateRefQty, _fromUnit];
}

/// <summary>
/// Bug 409083: UAT Finance Food - Duplicate vendor rebate payment
/// Check whether posted transactions exist for the current date period and consolidated rebate
/// </summary>
/// <param name = "_rebateDate"> rebate date </param>
/// <param name = "_rebateFromDate"> from date </param>
/// <param name = "_rebateToDate"> to date </param>
protected void updateRebateJournalTransPeriod(TAMRebateDate _rebateDate, FromDate _rebateFromDate, ToDate _rebateToDate)
{
    next updateRebateJournalTransPeriod(_rebateDate, _rebateFromDate, _rebateToDate);

    TAMRebateDateTrans rebateDateTransCons;
    TAMRebateId rebateIdCons = rebateDeal.RebateReconciliation == TAMRebateReconciliation::Deal ? '' : rebateTable.RebateId;
    TAMRebateTrans rebateTrans;

    // Check whether posted transactions exist for the current date period and consolidated rebate
    // that are included in TAMRebateTrans but do not exist in TAMRebateDateTrans.

    if (rebateTransactionType == TAMRebateTransactionType::Rebate 
        && rebateDeal.METInvoiceConsolidationByRebateType)
    {
        select firstonly RecId from rebateDateTransCons
                where rebateDateTransCons.RebateTransactionType == rebateTransactionType
                    && rebateDateTransCons.RebatePosted
                    && rebateDateTransCons.RebateFromDate >= rebateJournalTrans.parmRebateFromDate()
                    && rebateDateTransCons.RebateToDate <= rebateJournalTrans.parmRebateToDate()
                    && rebateDateTransCons.RebateDeal == rebateDeal.RecId
                    && rebateDateTransCons.RebateId != rebateIdCons
            exists join rebateTrans
                where rebateTrans.RebateTransId == rebateDateTransCons.RebateTransId
                && rebateTrans.RebateId == rebateIdCons;

        consRebateTransExists = rebateDateTransCons.RecId != 0;
    }
}
